#include <iostream>
using namespace std;

class Queue {
private:
    int arr[4];
    int front;
    int rear;
    int count;
public:
    Queue() {
        front = 0;
        rear = -1;
        count = 0;
    }
    void enqueue(int value) {
        if (count == 4) {
            cout << "Queue is full" << endl;
            return;
        }
        rear = (rear + 1) % 4;
        arr[rear] = value;
        count++;
    }
    int dequeue() {
        int value = arr[front];
        front = (front + 1) % 4;
        count--;
        return value;
    }
};

int main() {
    Queue q;
    q.enqueue(1);
    q.enqueue(2);
    q.enqueue(3);
    q.enqueue(4);
    cout << "Out: " << q.dequeue() << endl;
    cout << "Out: " << q.dequeue() << endl;
    q.enqueue(5);
    q.enqueue(6);
    return 0;
}
